-- The till's role gets a neutral name (brief CF-03; D64, D65; review A1-P1, A2-P1). The layer
-- that holds the till's values (the authority for price, sale and existence, and the only source
-- that makes an item orderable) was named after one vendor: layer `barsy`, sources `barsy:<in_>`.
-- It becomes `till` and `till:<in_>`; the vendor stays only on the connection row
-- (`integrations.kind`). The `import` layer and `import:<profile>` sources leave with it:
-- spreadsheet import was dropped (D65), and no import row exists.
--
-- The check constraints are generated by drizzle-kit from src/schema.ts; the data part is written
-- by hand. One transaction (the migrator runs pending migrations in one), in this order:
--   0. the three rewritten tables stop forcing row-level security on their owner for the length
--      of this transaction, and stop touching `updated_at`: on a database whose owner does not
--      bypass RLS (Supabase's `postgres`) the owner would otherwise see no row at all, and a pure
--      rename should leave every other column as it was. Both come back at the end; nobody else
--      sees the tables meanwhile (ALTER TABLE holds an ACCESS EXCLUSIVE lock until commit);
--   1. pre-check: refuse if any `import` row exists;
--   2. drop the old checks (generated);
--   3. rewrite the stored values: layers, sources, the `source` of link events, asset origins;
--   4. re-add the checks with the new rules and names (generated), same strength as before;
--   5. post-check: refuse if any `barsy` layer or source is left.
-- Left alone on purpose: integrations.kind, job_runs.kind, actors (`integration:<in_>`),
-- source_links and source_records (no layer or source in them), and snapshots (no layer names).
-- `events` is append-only for the app role by its privileges; this owner migration rewrites it
-- once. Reverse: packages/db/migrations-reverse/0014_till_role.down.sql (not run by db:migrate).

-- 0. Owner access for the rewrite; undone at step 6.
ALTER TABLE "restro"."field_values" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."events" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."assets" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."field_values" DISABLE TRIGGER "field_values_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."assets" DISABLE TRIGGER "assets_touch_updated_at";--> statement-breakpoint

-- 1. Pre-check: spreadsheet import is gone (D65); a row of it must be dealt with by a person.
DO $$
DECLARE
  import_rows bigint;
BEGIN
  SELECT
    (SELECT count(*) FROM restro.field_values WHERE layer = 'import' OR source LIKE 'import:%')
    + (SELECT count(*) FROM restro.events WHERE layer = 'import' OR source LIKE 'import:%')
  INTO import_rows;
  IF import_rows > 0 THEN
    RAISE EXCEPTION '0014_till_role: % field_values or events rows use the import layer or an import source; the import layer is gone (D65). Remove them first.', import_rows;
  END IF;
END
$$;--> statement-breakpoint

-- 2. Drop the old checks (generated by drizzle-kit).
ALTER TABLE "restro"."assets" DROP CONSTRAINT "assets_origin";--> statement-breakpoint
ALTER TABLE "restro"."events" DROP CONSTRAINT "events_layer";--> statement-breakpoint
ALTER TABLE "restro"."events" DROP CONSTRAINT "events_source";--> statement-breakpoint
ALTER TABLE "restro"."field_values" DROP CONSTRAINT "field_values_venue_scope_barsy_only";--> statement-breakpoint
ALTER TABLE "restro"."field_values" DROP CONSTRAINT "field_values_barsy_provenance";--> statement-breakpoint
ALTER TABLE "restro"."field_values" DROP CONSTRAINT "field_values_layer";--> statement-breakpoint
ALTER TABLE "restro"."field_values" DROP CONSTRAINT "field_values_source";--> statement-breakpoint
ALTER TABLE "restro"."field_values" DROP CONSTRAINT "field_values_layer_matches_source";--> statement-breakpoint

-- 3. Rewrite the stored values. `barsy:<x>` becomes `till:<x>` (the integration id is kept).
UPDATE "restro"."field_values" SET "layer" = 'till' WHERE "layer" = 'barsy';--> statement-breakpoint
UPDATE "restro"."field_values" SET "source" = 'till:' || substr("source", 7) WHERE "source" LIKE 'barsy:%';--> statement-breakpoint
UPDATE "restro"."events" SET "layer" = 'till' WHERE "layer" = 'barsy';--> statement-breakpoint
UPDATE "restro"."events" SET "source" = 'till:' || substr("source", 7) WHERE "source" LIKE 'barsy:%';--> statement-breakpoint
-- Link events record `{source, external_type[, state]}`; their `source` names the till too.
UPDATE "restro"."events"
SET "old_value" = jsonb_set("old_value", '{source}', to_jsonb('till:' || substr("old_value" ->> 'source', 7)))
WHERE "op" IN ('linkSource', 'unlinkSource', 'setLinkState')
  AND jsonb_typeof("old_value") = 'object'
  AND "old_value" ->> 'source' LIKE 'barsy:%';--> statement-breakpoint
UPDATE "restro"."events"
SET "new_value" = jsonb_set("new_value", '{source}', to_jsonb('till:' || substr("new_value" ->> 'source', 7)))
WHERE "op" IN ('linkSource', 'unlinkSource', 'setLinkState')
  AND jsonb_typeof("new_value") = 'object'
  AND "new_value" ->> 'source' LIKE 'barsy:%';--> statement-breakpoint
UPDATE "restro"."assets" SET "origin" = 'connector' WHERE "origin" = 'barsy';--> statement-breakpoint

-- 4. Re-add the checks with the new rules (generated by drizzle-kit). Same strength: the layer
--    list loses only `import`, a source is `manual` or `till:<name>`, layer `till` <-> source
--    `till:`, venue scope and record + mapping version on the till layer only.
ALTER TABLE "restro"."assets" ADD CONSTRAINT "assets_origin" CHECK ("restro"."assets"."origin" in ('upload', 'connector'));--> statement-breakpoint
ALTER TABLE "restro"."events" ADD CONSTRAINT "events_layer" CHECK ("restro"."events"."layer" in ('till', 'manual', 'override') or "restro"."events"."layer" ~ '^edition:[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$');--> statement-breakpoint
ALTER TABLE "restro"."events" ADD CONSTRAINT "events_source" CHECK ("restro"."events"."source" = 'manual' or "restro"."events"."source" ~ '^till:[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$');--> statement-breakpoint
ALTER TABLE "restro"."field_values" ADD CONSTRAINT "field_values_venue_scope_till_only" CHECK ("restro"."field_values"."scope" = 'master' or "restro"."field_values"."layer" = 'till');--> statement-breakpoint
ALTER TABLE "restro"."field_values" ADD CONSTRAINT "field_values_till_provenance" CHECK ("restro"."field_values"."layer" <> 'till' or ("restro"."field_values"."source_record_id" is not null and "restro"."field_values"."mapping_version" is not null));--> statement-breakpoint
ALTER TABLE "restro"."field_values" ADD CONSTRAINT "field_values_layer" CHECK ("restro"."field_values"."layer" in ('till', 'manual', 'override') or "restro"."field_values"."layer" ~ '^edition:[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$');--> statement-breakpoint
ALTER TABLE "restro"."field_values" ADD CONSTRAINT "field_values_source" CHECK ("restro"."field_values"."source" = 'manual' or "restro"."field_values"."source" ~ '^till:[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$');--> statement-breakpoint
ALTER TABLE "restro"."field_values" ADD CONSTRAINT "field_values_layer_matches_source" CHECK (("restro"."field_values"."layer" = 'till') = ("restro"."field_values"."source" like 'till:%'));--> statement-breakpoint

-- 5. Post-check: no vendor name is left in a layer, a source, a link event or an asset origin.
DO $$
DECLARE
  left_over bigint;
BEGIN
  SELECT
    (SELECT count(*) FROM restro.field_values WHERE layer = 'barsy' OR source LIKE 'barsy:%')
    + (SELECT count(*) FROM restro.events WHERE layer = 'barsy' OR source LIKE 'barsy:%')
    + (SELECT count(*) FROM restro.events
         WHERE op IN ('linkSource', 'unlinkSource', 'setLinkState')
           AND (old_value ->> 'source' LIKE 'barsy:%' OR new_value ->> 'source' LIKE 'barsy:%'))
    + (SELECT count(*) FROM restro.assets WHERE origin = 'barsy')
  INTO left_over;
  IF left_over > 0 THEN
    RAISE EXCEPTION '0014_till_role: % rows still name the barsy layer, source or origin', left_over;
  END IF;
END
$$;--> statement-breakpoint

-- 6. Back to normal: RLS forced on the owner again, updated_at touched again.
ALTER TABLE "restro"."field_values" ENABLE TRIGGER "field_values_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."assets" ENABLE TRIGGER "assets_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."field_values" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."events" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."assets" FORCE ROW LEVEL SECURITY;
